// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Retirement records are durable: intents written while a pinned SNAPSHOT reader blocked reclamation must survive a
 * store shutdown and be drained (with a fresh liveness re-check) when the store reopens, since no pre-restart reader
 * can exist anymore.
 */
public class LmdbValueGcRecoveryTest {

	@TempDir
	File dataDir;

	@Test
	public void retirementsRecoveredAfterRestart() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI pred = vf.createIRI("http://example.com/p");
		IRI subjectV = vf.createIRI("http://example.com/v");
		File storeDir = new File(dataDir, "store");

		LmdbStore store = new LmdbStore(storeDir, new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subjectV, pred, vf.createLiteral("v-value"));
				connection.addStatement(vf.createIRI("http://example.com/keeper"), pred, vf.createLiteral("keep"));
				connection.commit();
			}
			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(reader, subjectV, pred)).containsExactly("v-value");

				// removal behind the pinned reader: intents are recorded instead of reclaiming
				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.removeStatements(subjectV, pred, null);
					writer.commit();
				}
				reader.commit();
			}
			// v's dictionary entries are still intact: reclamation never ran (no draining commit followed)
			ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
			assertThat(valueStore.getId(vf.createIRI("http://example.com/v"))).isNotEqualTo(LmdbValue.UNKNOWN_ID);
		} finally {
			store.shutDown();
		}

		// reopen: no pre-restart reader exists, so open-time recovery drains the durable records
		store = new LmdbStore(storeDir, new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
			assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
					.as("retired subject IRI must be reclaimed during open-time recovery")
					.isEqualTo(LmdbValue.UNKNOWN_ID);
			assertThat(valueStore.getId(vf.createLiteral("v-value")))
					.as("retired literal must be reclaimed during open-time recovery")
					.isEqualTo(LmdbValue.UNKNOWN_ID);
			assertThat(valueStore.hasRetiredIds())
					.as("recovery must leave no pending retirement records")
					.isFalse();

			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(connection, vf.createIRI("http://example.com/keeper"), pred))
						.as("live values must be untouched by recovery")
						.containsExactly("keep");
				connection.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	public void boundedRecoveryDrainsEverything() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI pred = vf.createIRI("http://example.com/p");
		File storeDir = new File(dataDir, "store");

		LmdbStore store = new LmdbStore(storeDir, new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				for (int i = 0; i < 5; i++) {
					connection.addStatement(vf.createIRI("http://example.com/doomed" + i), pred,
							vf.createLiteral("doomed-value-" + i));
				}
				connection.addStatement(vf.createIRI("http://example.com/keeper"), pred, vf.createLiteral("keep"));
				connection.commit();
			}
			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(reader, vf.createIRI("http://example.com/doomed0"), pred))
						.containsExactly("doomed-value-0");
				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					for (int i = 0; i < 5; i++) {
						writer.removeStatements(vf.createIRI("http://example.com/doomed" + i), pred, null);
					}
					writer.commit();
				}
				reader.commit();
			}
		} finally {
			store.shutDown();
		}

		// a batch bound of 1 forces many poll/remove/gc rounds within a single open-time recovery
		System.setProperty("rdf4j.lmdb.valueGc.drainBatchSize", "1");
		try {
			store = new LmdbStore(storeDir, new LmdbStoreConfig("spoc,posc"));
			store.init();
			try {
				ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
				for (int i = 0; i < 5; i++) {
					assertThat(valueStore.getId(vf.createIRI("http://example.com/doomed" + i)))
							.as("doomed%d must be reclaimed by the bounded recovery loop", i)
							.isEqualTo(LmdbValue.UNKNOWN_ID);
				}
				assertThat(valueStore.hasRetiredIds()).isFalse();
				assertThat(valueStore.getId(vf.createIRI("http://example.com/keeper")))
						.isNotEqualTo(LmdbValue.UNKNOWN_ID);
			} finally {
				store.shutDown();
			}
		} finally {
			System.clearProperty("rdf4j.lmdb.valueGc.drainBatchSize");
		}
	}

	private static List<String> readObjects(NotifyingSailConnection connection, IRI subject, IRI predicate) {
		try (CloseableIteration<? extends Statement> statements = connection.getStatements(subject, predicate, null,
				false)) {
			return statements.stream().map(st -> st.getObject().stringValue()).sorted().collect(Collectors.toList());
		}
	}
}
